package com.kashibanaras.ecommerce.controller;
import com.kashibanaras.ecommerce.dto.ApiResponse; import com.kashibanaras.ecommerce.entity.*; import com.kashibanaras.ecommerce.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/addresses") public class AddressController{final UserRepository users;final AddressRepository r;public AddressController(UserRepository u,AddressRepository r){users=u;this.r=r;}@GetMapping public ApiResponse<?> all(Authentication a){return ApiResponse.success("Addresses",r.findByUserId((Long)a.getCredentials()));}record Req(String label,String fullName,String phone,String line1,String line2,String city,String state,String postalCode,String country,boolean isDefault){}@PostMapping public ApiResponse<?> add(Authentication a,@RequestBody Req x){User u=users.findById((Long)a.getCredentials()).orElseThrow();if(x.isDefault())r.findByUserId(u.getId()).forEach(z->z.setDefault(false));Address ad=Address.builder().user(u).label(x.label()).fullName(x.fullName()).phone(x.phone()).line1(x.line1()).line2(x.line2()).city(x.city()).state(x.state()).postalCode(x.postalCode()).country(x.country()==null?"India":x.country()).isDefault(x.isDefault()).build();return ApiResponse.success("Address saved",r.save(ad));}}
